{
  "root_causes": [
    {
      "service": "ts-payment-service",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name AS pod, round(value,3) AS cpu_cores FROM abnormal_metrics WHERE service_name='ts-payment-service' AND metric='container.cpu.usage' AND value > 1 ORDER BY time",
          "claim": "Payment container CPU jumps from about 0.01 to 3.6–3.9 cores for roughly 40 seconds, near its ~4.3-core limit."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) AS normal_avg, round(max(value),3) AS normal_max FROM normal_metrics WHERE service_name='ts-payment-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY metric",
          "claim": "In the normal period payment CPU averaged about 0.01 cores with a maximum near 0.02, far below the abnormal burst."
        },
        {
          "kind": "trace",
          "sql": "SELECT substr(cast(time as varchar),12,8) t, service_name, span_name, attr_span_kind kind, round(duration/1e6,1) ms, attr_status_code st, attr_http_response_status_code sc FROM abnormal_traces WHERE service_name='ts-inside-payment-service' AND span_name='POST' AND attr_span_kind='Client' AND attr_http_response_status_code=503 ORDER BY time",
          "claim": "Inside-payment's calls to payment return 503 after about 3.5 seconds during the CPU burst, 10:07:48 to 10:08:00."
        },
        {
          "kind": "trace",
          "sql": "SELECT substr(cast(time as varchar),12,8) t, service_name, span_name, round(duration/1e6,1) ms, attr_http_response_status_code sc FROM abnormal_traces WHERE service_name='ts-payment-service' AND attr_span_kind='Server' ORDER BY time",
          "claim": "Payment server spans appear at 10:08:06 with 2.3 s latency, and are absent for the failed 503 calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-payment-service",
      "to": "ts-inside-payment-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, attr_status_code st, attr_http_response_status_code sc, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name IN ('ts-inside-payment-service') AND span_name IN ('POST','POST /api/v1/inside_pay_service/inside_payment') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Inside-payment's inbound inside_payment POST spans show 8 errors with about 3.5 s latency, matching its failed payment calls."
        }
      ]
    },
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, attr_status_code st, attr_http_response_status_code sc, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE span_name LIKE '%inside_payment%' AND service_name IN ('ts-ui-dashboard','loadgenerator') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "The user-facing inside_payment path slows to 20 s at the entry point, with one user request erroring."
        }
      ]
    }
  ]
}
